// Reads site/tokens.css (generated by crates/report) and parses CSS colours.
//
// Used by scripts/check-colors.mjs, which fails the build on any colour outside the tokens,
// and by ec.config.mjs, which builds the code-block theme from the same values.

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

/** site/tokens.css, the generated token file. */
export const TOKENS_CSS = fileURLToPath(new URL('../tokens.css', import.meta.url));

/**
 * Every custom property declared in tokens.css, in order: Map of name (with `--`) to value.
 * Comments are dropped; values are trimmed.
 */
export function readTokens(path = TOKENS_CSS) {
  const css = readFileSync(path, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
  const tokens = new Map();
  for (const match of css.matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/g)) {
    tokens.set(match[1], match[2].trim());
  }
  return tokens;
}

/** The value of one token, or an error naming the token: the callers cannot work without it. */
export function token(tokens, name) {
  const value = tokens.get(name);
  if (value === undefined) throw new Error(`site/tokens.css does not declare ${name}`);
  return value;
}

// CSS Color 4 named colours, as "name rrggbb" pairs.
