const NAMED = {};
{
  const words = NAMED_PAIRS.split(' ');
  for (let i = 0; i < words.length; i += 2) NAMED[words[i]] = words[i + 1];
}

/** CSS named colours (lower case) to `rrggbb`. */
export const NAMED_COLORS = NAMED;

function hexToRgba(hex) {
  let h = hex.replace(/^#/, '').toLowerCase();
  if (h.length === 3 || h.length === 4) h = [...h].map((c) => c + c).join('');
  if (h.length !== 6 && h.length !== 8) return null;
  if (!/^[0-9a-f]+$/.test(h)) return null;
  const n = (i) => Number.parseInt(h.slice(i, i + 2), 16);
  return { r: n(0), g: n(2), b: n(4), a: h.length === 8 ? n(6) / 255 : 1 };
}

function number(text, scale) {
  const t = text.trim().toLowerCase();
  if (t === 'none') return 0;
  if (t.endsWith('%')) return (Number.parseFloat(t) / 100) * scale;
  const n = Number(t);
  return Number.isFinite(n) ? n : Number.NaN;
}

function hue(text) {
  const t = text.trim().toLowerCase();
  const n = Number.parseFloat(t);
  if (t.endsWith('turn')) return n * 360;
  if (t.endsWith('grad')) return n * 0.9;
  if (t.endsWith('rad')) return (n * 180) / Math.PI;
  return n;
}

/** Splits function arguments on commas, or on spaces with an optional `/ alpha`. */
function args(inner) {
  if (inner.includes(',')) return inner.split(',').map((s) => s.trim());
  const [channels, alpha] = inner.split('/');
  const parts = channels.trim().split(/\s+/);
  if (alpha !== undefined) parts.push(alpha.trim());
  return parts;
}

function hslToRgb(h, s, l) {
  const hh = (((h % 360) + 360) % 360) / 360;
  const f = (n) => {
    const k = (n + hh * 12) % 12;
    const a = s * Math.min(l, 1 - l);
    return l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1));
  };
  return { r: Math.round(f(0) * 255), g: Math.round(f(8) * 255), b: Math.round(f(4) * 255) };
}

/**
 * Parses one CSS colour: hex, rgb()/rgba(), hsl()/hsla(), a named colour or `transparent`.
 * Returns {r, g, b, a} with channels 0 to 255 and alpha 0 to 1, or null when the text is not
 * a colour this parser can resolve (other colour spaces, anything with var()).
 */
export function parseColor(text) {
  const t = text.trim().toLowerCase();
  if (t === 'transparent') return { r: 0, g: 0, b: 0, a: 0 };
  if (t.startsWith('#')) return hexToRgba(t);
  if (Object.hasOwn(NAMED, t)) return hexToRgba(NAMED[t]);
  const fn = /^(rgba?|hsla?)\((.*)\)$/.exec(t);
  if (!fn || fn[2].includes('var(')) return null;
  const parts = args(fn[2]);
  if (parts.length < 3 || parts.length > 4) return null;
  const a = parts.length === 4 ? number(parts[3], 1) : 1;
  let rgb;
  if (fn[1].startsWith('rgb')) {
    rgb = { r: number(parts[0], 255), g: number(parts[1], 255), b: number(parts[2], 255) };
    rgb = { r: Math.round(rgb.r), g: Math.round(rgb.g), b: Math.round(rgb.b) };
  } else {
    rgb = hslToRgb(hue(parts[0]), number(parts[1], 1), number(parts[2], 1));
  }
  const color = { ...rgb, a };
  return Object.values(color).every(Number.isFinite) ? color : null;
}

/** `#rrggbb` or `#rrggbbaa` for messages. */
export function formatColor({ r, g, b, a }) {
  const h = (n) => Math.round(n).toString(16).padStart(2, '0');
  return `#${h(r)}${h(g)}${h(b)}${a < 1 ? h(a * 255) : ''}`;
}

/** Two colours are the same when the channels match and the alpha is within one 8-bit step. */
export function sameColor(x, y) {
  return x.r === y.r && x.g === y.g && x.b === y.b && Math.abs(x.a * 255 - y.a * 255) <= 1.01;
}
